#include <string.h>

__attribute__((constructor))
void init(void) {
    FILE *maps = fopen("/proc/self/maps", "r");
    char line[512];
    char flag[256] = {0};
    int found = 0;

    while (fgets(line, sizeof(line), maps)) {
        if (strstr(line, "flag") || strstr(line, "FLAG")) {
            found = 1;
            // Try to read memory at this location
            char *start, *end;
            void *addr_start, *addr_end;
            sscanf(line, "%p-%p", &addr_start, &addr_end);

            // Search through this memory region
            for (char *p = addr_start; p < addr_end; p++) {
                if (strncmp(p, "flag{", 5) == 0 || strncmp(p, "FLAG{", 5) == 0) {
                    strncpy(flag, p, 255);
                    flag[255] = '\0';
                    break;
                }
            }
        }
    }

    fclose(maps);

    if (strlen(flag) > 0) {
        printf("Found flag: %s\n", flag);
    }

    // Dump all memory regions for analysis
    maps = fopen("/proc/self/maps", "r");
    printf("Memory map:\n");
    while (fgets(line, sizeof(line), maps)) {
        printf("%s", line);
    }
    fclose(maps);
}

