    fclose(maps);

    // Dump memory for interesting strings
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "cat /proc/%d/maps", getpid());
    system(cmd);

    // Look for flag in memory
    FILE *mem = fopen("/proc/self/mem", "rb");
    if (mem) {
        char buf[4096];
        while (fread(buf, 1, sizeof(buf), mem) > 0) {
            if (strstr(buf, "flag{")) {
                printf("Found flag pattern: %.100s\n", buf);
            }
        }
        fclose(mem);
    }
}

