#include <sys/mman.h>
#include <link.h>

static int callback(struct dl_phdr_info *info, size_t size, void *data) {
    printf("Name: %s\n", info->dlpi_name);
    for (int j = 0; j < info->dlpi_phnum; j++) {
        printf("\t[%2d] address=%10p\n", j,
               (void *) (info->dlpi_addr + info->dlpi_phdr[j].p_vaddr));
    }
    return 0;
}

__attribute__((constructor))
void init(void) {
    // Print process mappings
    FILE *fp = fopen("/proc/self/maps", "r");
    if (fp != NULL) {
        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            printf("Memory mapping: %s", line);
        }
        fclose(fp);
    }

    // Print loaded libraries
    dl_iterate_phdr(callback, NULL);

    // Try to find the flag in memory
    FILE *f = fopen("/proc/self/mem", "rb");
    if (f != NULL) {
        char buf[4096];
        char *pattern = "flag{";
        while (fread(buf, 1, sizeof(buf), f) > 0) {
            char *pos = strstr(buf, pattern);
            if (pos != NULL) {
                char flag[100];
                int i;
                for (i = 0; i < 99 && pos[i] != '}'; i++) {
                    flag[i] = pos[i];
                }
                flag[i+1] = '}';
                flag[i+2] = '\0';
                printf("Found flag: %s\n", flag);
                break;
            }
        }
        fclose(f);
    }
}
